const j = $input.first().json || {};
const wf = j.workflow || {};
const ex = j.execution || {};
const err = ex.error || {};

// Fehler aus einem aufgerufenen Sub-Workflow (z. B. WF03 unter WF02): Der Sub-Workflow
// meldet sich selbst, der aufrufende Workflow soll keine zweite Mail schicken.
if (err.workflowId && wf.id && String(err.workflowId) !== String(wf.id)) {
  return [];
}

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const name = String(wf.name || 'Unbekannter Workflow');
const node = String(err.node && err.node.name ? err.node.name : (ex.lastNodeExecuted || 'unbekannt'));
const msg = String(err.message || 'Keine Fehlermeldung uebermittelt');
const desc = String(err.description || '');
const url = String(ex.url || '');
const zeit = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px">' +
  '<h2 style="font-size:18px;margin:0 0 4px 0;color:#b42318">Workflow abgebrochen</h2>' +
  '<p style="font-size:13px;color:#777;margin:0 0 16px 0">' + esc(zeit) + '</p>' +
  '<table style="border-collapse:collapse;font-size:13px">' +
  '<tr><td style="padding:6px 14px 6px 0;color:#777">Workflow</td><td style="padding:6px 0"><b>' + esc(name) + '</b></td></tr>' +
  '<tr><td style="padding:6px 14px 6px 0;color:#777">Node</td><td style="padding:6px 0"><b>' + esc(node) + '</b></td></tr>' +
  '</table>' +
  '<div style="margin:16px 0;padding:12px;background:#fdf2f2;border-left:4px solid #b42318;font-size:13px">' + esc(msg) + (desc ? '<br><br><span style="color:#555">' + esc(desc) + '</span>' : '') + '</div>' +
  (url ? '<p><a href="' + url + '" style="background:#0b5cad;color:#ffffff;padding:10px 20px;border-radius:4px;text-decoration:none;font-size:14px">Ausfuehrung in n8n oeffnen</a></p>' : '') +
  '<p style="font-size:12px;color:#777">Achtung: Ein erneuter Lauf startet den Workflow von vorn und wiederholt alle bereits erfolgten Schritte inklusive kostenpflichtiger API-Aufrufe. Lieber gezielt reparieren als blind neu starten.</p>' +
  '</div>';

return [{ json: { betreff: 'n8n-Fehler: ' + name + ' (' + node + ')', html: html } }];
